def transform(grid):
    n = next(j for j, value in enumerate(grid[0]) if value == 5)
    starts = [0] + [j + 1 for j, value in enumerate(grid[0]) if value == 5]
    starts = [s for s in starts if s + n <= len(grid[0])]

    marker_row = next(
        r for r in range(2 * n + 1, len(grid))
        if any(value not in (0, 5) for value in grid[r])
    )

    patterns = {}
    targets = {}
    for s in starts:
        colors = {}
        for r in range(n):
            for c in range(n):
                value = grid[r][s + c]
                if value not in (0, 5):
                    colors.setdefault(value, set()).add((r, c))
        if colors:
            source = max(colors, key=lambda color: len(colors[color]))
            patterns[source] = colors[source]
            targets[source] = grid[marker_row][s + n // 2]

    out = [[0] * (n * n) for _ in range(n * n)]
    for s in starts:
        for r in range(n):
            for c in range(n):
                source = grid[n + 1 + r][s + c]
                if source not in patterns:
                    continue
                color = targets[source]
                for dr, dc in patterns[source]:
                    out[r * n + dr][c * n + dc] = color

    return out
